package com.primehr.rsp.screening.application;
import com.primehr.integration.administrative.*; import com.primehr.integration.humanresource.*; import com.primehr.security.RspApplicationScreeningPermissionGuard; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service;
@Service public class ScreeningAssignmentEligibilityService {private final HumanResourceEmployeeDirectoryClient employees;private final AdministrativeAuthorizationClient authorization;public ScreeningAssignmentEligibilityService(HumanResourceEmployeeDirectoryClient employees,AdministrativeAuthorizationClient authorization){this.employees=employees;this.authorization=authorization;}public void validate(String screener,String validator,String token){if(screener.equalsIgnoreCase(validator))throw new IllegalArgumentException("Screener and validator must be different employees");require(screener,true,token);require(validator,false,token);}private void require(String employee,boolean screener,String token){var target=employees.require(employee,token);var p=authorization.resolveEmployee(RspApplicationScreeningPermissionGuard.FEATURE,target.employeeNo(),target.role(),token);boolean actions=screener?p.canEdit()&&p.canSubmit():p.canApprove();if(!p.administrator()&&(!p.canAccess()||!actions||p.dataScope()!=PermissionDataScope.AGENCY_WIDE))throw new AccessDeniedException("Assigned "+(screener?"screener":"validator")+" lacks required application-screening permission");}}
